def is_bipartite(graph: Dict[int, List[int]]) -> bool:
    """Check if the undirected graph can be 2-colored without adjacent conflicts."""
    color: Dict[int, int] = {}

    for start in graph:
        if start not in color:
            color[start] = 0
            queue = deque([start])
            while queue:
                u = queue.popleft()
                for v in graph.get(u, []):
                    if v not in color:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        return False
    return True

