def length_of_lis(nums: List[int]) -> int:
    """Determine the length of the longest strictly increasing subsequence in O(N log N)."""
    tails: List[int] = []
    for x in nums:
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

