def find_articulation_points(graph: Dict[int, List[int]]) -> Set[int]:
    """Find all cut vertices whose removal increases connected components."""
    discovery_time = {}
    low = {}
    visited = set()
    cut_vertices = set()
    timer = 0

    def dfs(u: int, parent: int = -1) -> None:
        nonlocal timer
        visited.add(u)
        discovery_time[u] = low[u] = timer
        timer += 1
        children = 0

        for v in graph.get(u, []):
            if v == parent:
                continue
            if v in visited:
                low[u] = min(low[u], discovery_time[v])
            else:
                children += 1
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if parent != -1 and low[v] >= discovery_time[u]:
                    cut_vertices.add(u)
        if parent == -1 and children > 1:
            cut_vertices.add(u)

    for node in graph:
        if node not in visited:
            dfs(node)

    return cut_vertices

