def word_break(s: str, word_dict: List[str]) -> bool:
    """Determine if string s can be partitioned into dictionary words using DP."""
    words: Set[str] = set(word_dict)
    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True

    for i in range(1, n + 1):
        for j in range(i):
            if dp[j] and s[j:i] in words:
                dp[i] = True
                break

    return dp[n]

