def counting_sort(arr: List[int], max_val: int) -> List[int]:
    """Perform stable counting sort on non-negative integers up to max_val."""
    counts = [0] * (max_val + 1)
    for x in arr:
        counts[x] += 1
    output = []
    for val, count in enumerate(counts):
        output.extend([val] * count)
    return output

