def kosaraju_scc(graph: Dict[str, List[str]]) -> List[List[str]]:
    """Find all strongly connected components using Kosaraju's two-pass DFS."""
    stack: List[str] = []
    visited: Set[str] = set()

    def fill_order(u: str) -> None:
        visited.add(u)
        for v in graph.get(u, []):
            if v not in visited:
                fill_order(v)
        stack.append(u)

    for node in graph:
        if node not in visited:
            fill_order(node)

    # Build transpose graph
    transpose: Dict[str, List[str]] = {n: [] for n in graph}
    for u in graph:
        for v in graph[u]:
            transpose.setdefault(v, []).append(u)

    visited.clear()
    sccs = []

    def dfs_collect(u: str, comp: List[str]) -> None:
        visited.add(u)
        comp.append(u)
        for v in transpose.get(u, []):
            if v not in visited:
                dfs_collect(v, comp)

    while stack:
        u = stack.pop()
        if u not in visited:
            comp: List[str] = []
            dfs_collect(u, comp)
            sccs.append(comp)

    return sccs

