def graph_diameter_bfs(graph: Dict[str, List[str]]) -> int:
    """Compute the maximum shortest path between any two vertices in graph."""
    max_diameter = 0

    for start in graph:
        dist = {start: 0}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            d = dist[u]
            max_diameter = max(max_diameter, d)
            for v in graph.get(u, []):
                if v not in dist:
                    dist[v] = d + 1
                    queue.append(v)

    return max_diameter

