        self.right: Optional[SNode] = None

class SplayMap:
    """Key-value dictionary backed by a splay tree."""
    def __init__(self):
        self.root: Optional[SNode] = None

    def _right_rot(self, node: SNode) -> SNode:
        left = node.left
        assert left is not None
        node.left = left.right
        left.right = node
        return left

    def _left_rot(self, node: SNode) -> SNode:
        right = node.right
        assert right is not None
        node.right = right.left
        right.left = node
        return right

    def insert(self, key: int, val: Any) -> None:
        if not self.root:
            self.root = SNode(key, val)
            return
        curr = self.root
        while True:
            if key < curr.key:
                if not curr.left:
                    curr.left = SNode(key, val)
                    break
                curr = curr.left
            elif key > curr.key:
                if not curr.right:
                    curr.right = SNode(key, val)
                    break
                curr = curr.right
            else:
                curr.val = val
                break

class FenwickTree:
    """Binary Indexed Tree for efficient prefix sums and point updates."""
    def __init__(self, size: int):
        self.size = size
        self.tree = [0] * (size + 1)

    def update(self, index: int, delta: int) -> None:
        """Add delta to the element at the given 1-based index."""
        while index <= self.size:
            self.tree[index] += delta
            index += index & (-index)

    def query(self, index: int) -> int:
        """Compute the prefix sum from index 1 to the given 1-based index."""
        total = 0
        while index > 0:
            total += self.tree[index]
            index -= index & (-index)
        return total

class DisjointSetUnion:
    """Disjoint Set Union with path compression and rank optimization."""
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x: int) -> int:
        """Find the representative root of element x with path compression."""
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x: int, y: int) -> bool:
        """Union the sets containing x and y. Returns True if merged, False if already in same set."""
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x == root_y:
            return False
        if self.rank[root_x] < self.rank[root_y]:
            self.parent[root_x] = root_y
        elif self.rank[root_x] > self.rank[root_y]:
            self.parent[root_y] = root_x
        else:
            self.parent[root_y] = root_x
            self.rank[root_x] += 1
        return True

from typing import List

class SegmentTree:
    """Segment Tree for efficient range sum queries and point updates."""
    def __init__(self, data: List[int]):
        self.n = len(data)
        self.tree = [0] * (4 * self.n)
        if self.n > 0:
            self._build(data, 0, 0, self.n - 1)

    def _build(self, data: List[int], node: int, start: int, end: int) -> None:
        if start == end:
            self.tree[node] = data[start]
            return
        mid = (start + end) // 2
        left = 2 * node + 1
        right = 2 * node + 2
        self._build(data, left, start, mid)
        self._build(data, right, mid + 1, end)
        self.tree[node] = self.tree[left] + self.tree[right]

    def query(self, l: int, r: int, node: int = 0, start: int = 0, end: int = -1) -> int:
        if end == -1:
            end = self.n - 1
        if r < start or l > end or start > end:
            return 0
        if l <= start and end <= r:
            return self.tree[node]
        mid = (start + end) // 2
        left_sum = self.query(l, r, 2 * node + 1, start, mid)
        right_sum = self.query(l, r, 2 * node + 2, mid + 1, end)
        return left_sum + right_sum

