def exponential_moving_average(series: List[float], alpha: float = 0.3) -> List[float]:
    """Compute EMA series for given smoothing factor alpha in (0, 1]."""
    if not series:
        return []
    ema = [series[0]]
    for x in series[1:]:
        val = alpha * x + (1.0 - alpha) * ema[-1]
        ema.append(val)
    return ema

