def convolve_1d(signal: List[float], kernel: List[float]) -> List[float]:
    """Perform 1D discrete linear convolution of signal and kernel."""
    n, m = len(signal), len(kernel)
    out_len = n + m - 1
    result = [0.0] * out_len
    for i in range(n):
        for j in range(m):
            result[i + j] += signal[i] * kernel[j]
    return result

