    n = len(x)
    if n != len(y) or n < 2:
        raise ValueError("Vectors must have matching length >= 2")
    mx = sum(x) / n
    my = sum(y) / n
    return sum((x[i] - mx) * (y[i] - my) for i in range(n)) / (n - 1)

