def simpsons_three_eighths(func, a: float, b: float, n: int = 99) -> float:
    """Compute definite integral using composite Simpson's 3/8 rule (n must be multiple of 3)."""
    if n % 3 != 0:
        n = (n // 3 + 1) * 3
    h = (b - a) / n
    total = func(a) + func(b)
    for i in range(1, n):
        x = a + i * h
        if i % 3 == 0:
            total += 2 * func(x)
        else:
            total += 3 * func(x)
    return (3 * h / 8) * total

