def qr_decomposition_mgs(A: List[List[float]]) -> Tuple[List[List[float]], List[List[float]]]:
    """Compute QR decomposition using Modified Gram-Schmidt orthogonalization."""
    m = len(A)
    n = len(A[0])
    Q = [[A[i][j] for j in range(n)] for i in range(m)]
    R = [[0.0] * n for _ in range(n)]
    for k in range(n):
        norm = math.sqrt(sum(Q[i][k] ** 2 for i in range(m)))
        R[k][k] = norm
        if norm > 1e-12:
            for i in range(m):
                Q[i][k] /= norm
        for j in range(k + 1, n):
            dot = sum(Q[i][k] * Q[i][j] for i in range(m))
            R[k][j] = dot
            for i in range(m):
                Q[i][j] -= dot * Q[i][k]
    return Q, R

def newton_raphson(func, dfunc, x0: float, tol: float = 1e-7, max_iter: int = 100) -> float:
    """Find root of func(x) = 0 using Newton-Raphson iteration."""
    x = x0
    for _ in range(max_iter):
        y = func(x)
        dy = dfunc(x)
        if abs(dy) < 1e-14:
            break
        x_next = x - y / dy
        if abs(x_next - x) < tol:
            return x_next
        x = x_next
    return x

def bisection_root(func, a: float, b: float, tol: float = 1e-7, max_iter: int = 100) -> float:
    """Locate root of func(x) = 0 in [a, b] using bisection."""
    if func(a) * func(b) >= 0:
        raise ValueError("func(a) and func(b) must have opposite signs")
    for _ in range(max_iter):
        mid = (a + b) / 2.0
        f_mid = func(mid)
        if abs(f_mid) < tol or (b - a) / 2.0 < tol:
            return mid
        if func(a) * f_mid < 0:
            b = mid
        else:
            a = mid
    return (a + b) / 2.0

