def companion_matrix_monic(coeffs: List[float]) -> List[List[float]]:
    """Construct Frobenius companion matrix for monic polynomial x^n + c_{n-1}*x^{n-1} + ... + c_0."""
    n = len(coeffs)
    C = [[0.0] * n for _ in range(n)]
    for i in range(n - 1):
        C[i + 1][i] = 1.0
    for i in range(n):
        C[i][-1] = -coeffs[i]
    return C

