def soft_threshold(v: List[float], threshold: float) -> List[float]:
    """Apply shrinkage/soft-thresholding operator S_threshold(x) elementwise."""
    res = []
    for x in v:
        if x > threshold:
            res.append(x - threshold)
        elif x < -threshold:
            res.append(x + threshold)
        else:
            res.append(0.0)
    return res

def secant_root_finder(f, x0: float, x1: float, tol: float = 1e-7, max_iter: int = 50) -> float:
    """Find root of f(x) = 0 using secant iteration."""
    f0 = f(x0)
    f1 = f(x1)
    for _ in range(max_iter):
        if abs(f1 - f0) < 1e-15:
            break
        x2 = x1 - f1 * (x1 - x0) / (f1 - f0)
        if abs(x2 - x1) < tol:
            return x2
        x0, f0 = x1, f1
        x1, f1 = x2, f(x2)
    return x1

