def list_zip_entries(zip_bytes: bytes) -> List[Dict[str, Any]]:
    """Extract entry names and uncompressed sizes from zip buffer."""
    with zipfile.ZipFile(io.BytesIO(zip_bytes), mode="r") as zf:
        return [
