import hashlib
import io

def compute_stream_sha256(stream: io.BytesIO, chunk_size: int = 65536) -> str:
    """Compute hexadecimal SHA-256 digest of binary stream in chunks."""
    hasher = hashlib.sha256()
    while True:
        chunk = stream.read(chunk_size)
        if not chunk:
            break
        hasher.update(chunk)
    return hasher.hexdigest()

def validate_ipv4_octet_ranges(ip_str: str) -> bool:
    """Validate that string is a valid dotted-decimal IPv4 address."""
    parts = ip_str.strip().split(".")
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit() or (len(p) > 1 and p[0] == "0"):
            return False
        if not (0 <= int(p) <= 255):
            return False
    return True

def validate_tcp_port_number(port_str: str) -> bool:
    """Validate whether port string represents an integer in [1, 65535]."""
    if not port_str.isdigit():
        return False
    val = int(port_str)
    return 1 <= val <= 65535

def validate_cidr_prefix_length(cidr_str: str) -> bool:
    """Validate IPv4 CIDR string representation."""
    if "/" not in cidr_str:
        return False
    ip_part, mask_part = cidr_str.split("/", 1)
    if not mask_part.isdigit():
        return False
    mask = int(mask_part)
    if not (0 <= mask <= 32):
        return False
    octets = ip_part.split(".")
    if len(octets) != 4 or not all(o.isdigit() and 0 <= int(o) <= 255 for o in octets):
        return False
    return True

